function XUiPBRChapterGridStage:Refresh(stageId)
    local stageCfg = self._Control:GetStageCfgById(stageId)
    local isUnlock, lockDesc = XMVCA.XPBRGame:GetIsStageUnlockById(stageId)
    local isPassed = XMVCA.XPBRGame:CheckPassedByStageId(stageId)
    self.GridBtn:SetNameByGroup(0, stageCfg.StageName)
    self.GridBtn:SetNameByGroup(2, lockDesc)
    self.CommonFuBenClear.gameObject:SetActiveEx(isPassed)
    
    self.GridBtn:SetButtonState(isUnlock and CS.UiButtonState.Normal or CS.UiButtonState.Disable)
    
    if isUnlock then
        -- 显示首通奖励：目前UI只给了一个位置，先按一个奖励来显示
        local isShowReward = false

        if XTool.IsNumberValidEx(stageCfg.FinishRewards) then
            local rewardList = XRewardManager.GetRewardList(stageCfg.FinishRewards)

            if not XTool.IsTableEmpty(rewardList) then
                local rewardInfo = rewardList[1]

                if self._GridRewards == nil then
                    self._GridRewards = {}
                end

                for i, v in pairs(self.GridRewardGoList) do
                    ---@type XUiGridCommon
                    local grid = self._GridRewards[v]

                    if not grid then
                        grid = XUiHelper.XUiGridCommon(self.RootUi, v)

                        self._GridRewards[v] = grid
                    end

                    grid:Refresh(rewardInfo)
                    grid:SetReceived(isPassed)
                end

                isShowReward= true
            end
        end

        if not isShowReward then
            for i, v in pairs(self.GridRewardGoList) do
                v.gameObject:SetActiveEx(false)
            end
        end
        
        -- 显示关卡进度
        local curWaves, maxWaves = self._Control:GetStageProgressByStageId(stageId)
        
        self.GridBtn:SetNameByGroup(1, XUiHelper.FormatTextEx(self._Control:GetClientPBRText('StageProgressDesc'), curWaves, maxWaves))
        
        -- 显示红点
        self.GridBtn:ShowReddot(XMVCA.XPBRGame:ReddotIsStageNewUnlockById(stageId))
    end
    
    -- 无尽关标签
    for i = 1, 10 do
        local ui = self['TagEndless' .. i]

        if not ui then
            break
        end

        ui.gameObject:SetActiveEx(stageCfg.StageType == XMVCA.XPBRGame.EnumConst.StageCustomType.Challenge)
    end
    
    
    
    
    self.StageId = stageId
    self._IsUnlock = isUnlock
    self._LockDesc = lockDesc
end

function XUiPBRChapterGridStage:GetIsUnlock()
    return self._IsUnlock
end

function XUiPBRChapterGridStage:OnGridBtnClick()
    if self:GetIsUnlock() then
        self.Parent:OnGridStageClick(self.StageId)
        self._Control:ReddoSetStageMark(self.StageId)
    else
        XUiManager.TipMsg(self._LockDesc)
    end
end

function XUiPBRChapterGridStage:PlayCustomEnableAnimation(delayTime)
    if XTool.IsNumberValidEx(delayTime) then
        self:DelayCall(self._PlayCustomEnableAnimHandler, delayTime)
    else
        self._PlayCustomEnableAnimHandler()
    end
end

